#include <iostream>
#include <cmath>
#include <iomanip>
#include <limits>

/**
 * @brief Calculates the perpendicular distance from a point to a plane.
 * 
 * The formula used is: d = |Ax₀ + By₀ + Cz₀ + D| / sqrt(A² + B² + C²)
 * where the plane equation is Ax + By + Cz + D = 0.
 * 
 * @param px, py, pz Coordinates of the point.
 * @param a, b, c, d Coefficients of the plane (Ax + By + Cz + D = 0).
 * @return double The calculated distance.
 */
double calculateDistanceToPlane(double px, double py, double pz, double a, double b, double c, double d) {
    double numerator = std::abs(a * px + b * py + c * pz + d);
    double denominator = std::sqrt(std::pow(a, 2) + std::pow(b, 2) + std::pow(c, 2));

    // Avoid division by zero if all normal coefficients are zero
    if (denominator == 0.0) {
        return 0.0; // Graphically undefined, but mathematically treated as 0 here
    }

    return numerator / denominator;
}

/**
 * @brief Safely gets a floating-point number from the user.
 * 
 * @param prompt The message to display to the user.
 * @param value Reference to the variable storing the input.
 * @return true If valid input was provided.
 * @return false If input was invalid (non-numeric or out of reasonable bounds).
 */
bool getDoubleInput(const std::string& prompt, double& value) {
    std::cout << prompt;
    std::cin >> value;

    // Check if a number was actually extracted (cin evaluates to false if input fails)
    if (!std::cin) {
        std::cout << "Error: Invalid input. Please enter a numeric value.\n";
        // Clear the error flags and ignore the rest of the line
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        return false;
    }

    // Optional: Check if the number is finite (not inf or nan)
    if (!std::isfinite(value)) {
        std::cout << "Error: Input must be a finite number.\n";
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        return false;
    }

    return true;
}

int main() {
    double px, py, pz; // Point coordinates
    double a, b, c, d; // Plane coefficients

    std::cout << std::fixed << std::setprecision(2);

    std::cout << "=== Distance From Point to Plane Calculator ===\n\n";

    // Input Point Coordinates
    std::cout << "--- Point Coordinates (x, y, z) ---\n";
    if (!getDoubleInput("Enter x-coordinate: ", px) ||
        !getDoubleInput("Enter y-coordinate: ", py) ||
        !getDoubleInput("Enter z-coordinate: ", pz)) {
        std::cout << "\nProgram terminated due to input errors.\n";
        return 1;
    }

    // Input Plane Coefficients (Ax + By + Cz + D = 0)
    std::cout << "\n--- Plane Coefficients (Ax + By + Cz + D = 0) ---\n";
    if (!getDoubleInput("Enter coefficient A: ", a) ||
        !getDoubleInput("Enter coefficient B: ", b) ||
        !getDoubleInput("Enter coefficient C: ", c) ||
        !getDoubleInput("Enter coefficient D: ", d)) {
        std::cout << "\nProgram terminated due to input errors.\n";
        return 1;
    }

    // Calculate Distance
    double distance = calculateDistanceToPlane(px, py, pz, a, b, c, d);

    // Output Result
    std::cout << "\n--- Results ---\n";
    std::cout << "Point: (" << px << ", " << py << ", " << pz << ")\n";
    std::cout << "Plane Equation: " << a << "x + " << b << "y + " << c << "z + " << d << " = 0\n";
    std::cout << "Distance from point to plane: " << distance << " units\n";

    return 0
